/**
 * Chuẩn hóa metadata lâm sàng cho cả bài cũ và bài mới.
 * Giá trị suy luận chỉ là nhãn điều hướng, không thay thế thẩm định y khoa.
 */
for (const article of articles) {
  article.conditionCluster ??= article.specialty ?? article.categoryName;
  article.careStage ??= article.category === 'guidelines' ? 'prevention' : 'general';
  article.audience ??= (() => {
    const map: Record<string, string[]> = {
      'nhi-khoa': ['child', 'caregiver'],
      'san-khoa': ['pregnancy', 'postpartum'],
      'lao-khoa': ['elderly', 'caregiver'],
      'ung-thu': ['cancer', 'caregiver'],
      'ngoai-khoa': ['postoperative', 'caregiver'],
      'dinh-duong-the-thao': ['athlete', 'adult'],
    };
    return map[article.specialty ?? ''] ?? ['adult'];
  })();
  article.riskFlags ??= [];
  if (article.specialty && ['ung-thu', 'than-tiet-nieu', 'tim-mach', 'noi-tiet', 'tieu-hoa', 'san-khoa', 'nhi-khoa'].includes(article.specialty)) {
    if (!article.riskFlags.includes('needs-clinical-context')) article.riskFlags.push('needs-clinical-context');
  }
  article.sourceTier ??= article.sources?.some((source) => /WHO|NCI|ADA|AHA|NHS|NIDDK|NIH|CDC|KDIGO|ESPEN|ACR|Bộ Y tế/i.test(source.name))
    ? 'guideline'
    : article.sources?.length ? 'clinical-reference' : 'editorial';
  article.lastMedicalReview ??= article.reviewedAt ?? article.date;
}

// Index by slug for fast lookup
export const articleBySlug: Record<string, ArticleMeta> = {};
for (const a of articles) {
  articleBySlug[a.slug] = a;
}

export function getSeriesArticles(series: string): ArticleMeta[] {
  return articles.filter(a => a.series === series);
}

export function getFeaturedArticles(): ArticleMeta[] {
  return articles.filter(a => a.featured);
}

